  [811336] = {
    [1] = {
      beijing = 4310,
      dialog = 3,
      music = "47_Warm_Daily",
      renwu = "npc",
      sentence = "我和周棋洛走进仁寿殿前开阔的大院落，摆放在四周的太湖石一下子吸引了我们的注意。",
      next = {2}
    },
    [2] = {
      beijing = 4310,
      dialog = 2,
      idx = 3,
      music = "47_Warm_Daily",
      renming = "周棋洛",
      renwu = "npc",
      role1 = 327000,
      role2 = 301102,
      role3 = 301209,
      ruchang = -1,
      sentence = "这里的石头都好高啊！",
      next = {3}
    },
    [3] = {
      beijing = 4310,
      dhead = 113,
      dialog = 1,
      music = "47_Warm_Daily",
      renming = "$u",
      renwu = "npc",
      role1 = 327000,
      role2 = 301101,
      role3 = 301201,
      ruchang = 9,
      sentence = "我刚刚看了下介绍，它们应该就是那四块象征着春华、秋实、冬枯、夏荣的“四季石”吧！",
      next = {4}
    },
    [4] = {
      beijing = 4310,
      dialog = 3,
      music = "47_Warm_Daily",
      renwu = "npc",
      sentence = "边说着，我们又走到一个高大别致的太湖石前，我看了眼它前面的介绍，喃喃出声。",
      next = {5}
    },
    [5] = {
      beijing = 4310,
      dhead = 111,
      dialog = 1,
      music = "47_Warm_Daily",
      renming = "$u",
      renwu = "npc",
      sentence = "“寿星石”……",
      next = {6}
    },
    [6] = {
      beijing = 4310,
      dialog = 3,
      music = "47_Warm_Daily",
      renwu = "npc",
      sentence = "我有点不解地再次打量了下眼前的石头。",
      next = {7}
    },
    [7] = {
      beijing = 4310,
      dhead = 112,
      dialog = 1,
      music = "47_Warm_Daily",
      renming = "$u",
      renwu = "npc",
      sentence = "为什么它叫做“寿星石”呢？",
      next = {8}
    },
    [8] = {
