      dialog = 2,
      idx = 3,
      music = "47_Warm_Daily",
      renming = "周棋洛",
      renwu = "npc",
      role1 = 327000,
      role2 = 301101,
      role3 = 301203,
      ruchang = -1,
      sentence = "……我好像知道是为什么！",
      next = {9}
    },
    [9] = {
      beijing = 4310,
      dialog = 3,
      music = "47_Warm_Daily",
      renwu = "npc",
      role1 = 327000,
      role2 = 301102,
      role3 = 301201,
      sentence = "周棋洛眼珠一转，忽然佝偻起身子，有模有样地摆出一个姿势——",
      next = {10}
    },
    [10] = {
      beijing = 4310,
      dialog = 2,
      idx = 3,
      music = "47_Warm_Daily",
      renming = "周棋洛",
      renwu = "npc",
      role1 = 327000,
      role2 = 301101,
      role3 = 301201,
      sentence = "你看，我和它是不是很像？",
      next = {11}
    },
    [11] = {
      beijing = 4310,
      dialog = 3,
      music = "47_Warm_Daily",
      renwu = "npc",
      role1 = 327000,
      role2 = 301101,
      role3 = 301201,
      sentence = "经他这么一模仿，我惊喜地发现，这块太湖石的确像是一个拱手躬身的老人。",
      next = {12}
    },
    [12] = {
      beijing = 4310,
      dialog = 2,
      idx = 3,
      music = "47_Warm_Daily",
      renming = "周棋洛",
      renwu = "npc",
      role1 = 327000,
      role2 = 301101,
      role3 = 301201,
      sentence = "导览册上写着，它和其他四个太湖石一同被称为“峰虚五老”，象征庐山胜景“五老峰”，喻意长寿。",
      next = {13}
    },
    [13] = {
      beijing = 4310,
      dialog = 2,
