      music = "47_Warm_Daily",
      renming = "周棋洛",
      renwu = "npc",
      role1 = 327000,
      role2 = 301101,
      role3 = 301203,
      sentence = "那以后我们也捡五块石头，像这样放在家里，是不是也可以喻意长寿了？",
      next = {14}
    },
    [14] = {
      beijing = 4310,
      dialog = 3,
      music = "47_Warm_Daily",
      renwu = "npc",
      role1 = 327000,
      role2 = 301101,
      role3 = 301201,
      sentence = "周棋洛亮闪闪的目光投向我，我被他脑洞大开的想法逗得噗嗤一笑。",
      next = {15}
    },
    [15] = {
      beijing = 4310,
      dhead = 114,
      dialog = 1,
      music = "47_Warm_Daily",
      renming = "$u",
      renwu = "npc",
      role1 = 327000,
      role2 = 301101,
      role3 = 301201,
      sentence = "那应该还是有差别的。",
      next = {16}
    },
    [16] = {
      beijing = 4310,
      dialog = 3,
      music = "47_Warm_Daily",
      renwu = "npc",
      role1 = 327000,
      role2 = 301102,
      role3 = 301201,
      sentence = "周棋洛也笑了笑，他转眸看向前方不远处，忽然握住了我的手。",
      next = {17}
    },
    [17] = {
      beijing = 4310,
      dialog = 2,
