      music = "47_Warm_Daily",
      renming = "周棋洛",
      renwu = "npc",
      role1 = 327000,
      role2 = 301102,
      role3 = 301201,
      sentence = "我想再过五年、再过十年……等我们都变成老头头老奶奶后，也要来这里。",
      next = {18}
    },
    [18] = {
      beijing = 4310,
      dialog = 3,
      music = "47_Warm_Daily",
      renwu = "npc",
      role1 = 327000,
      role2 = 301102,
      role3 = 301201,
      sentence = "我顺着他的目光看去，发现有几对老年游者，正拿着相机拍照留念，虽然步履蹒跚但却兴致勃勃。",
      next = {19}
    },
    [19] = {
      beijing = 4310,
      dialog = 3,
      music = "47_Warm_Daily",
      renwu = "npc",
      role1 = 327000,
      role2 = 301101,
      role3 = 301201,
      sentence = "心底的某处被隐隐触动，我故意打趣地看向他，语气更轻柔了些。",
      next = {20}
    },
    [20] = {
