      renming = "Chen Yi",
      renwu = "npc",
      sentence = "Your Highness! Those Rongdi scoundrels attacked us when our guard was down. Out of the fifty thousand soldiers of our forward camp, I'm the only one left. If I can't even protect Your Highness, then how can I face my brothers in death?!",
